def _extract_number(value):
    # Direct number
    if isinstance(value, (int, float)):
        return value
    # Tuple or list: return the first numeric element
    if isinstance(value, (list, tuple)):
        for item in value:
            if isinstance(item, (int, float)):
                return item
    # Dictionary: return the first numeric value
    if isinstance(value, dict):
        for item in value.values():
            if isinstance(item, (int, float)):
                return item
    raise TypeError(f"Unable to extract numeric value from {value!r}")

result = _extract_number(_raw)

import vornik

def _extract(value):
    """Return the numeric part of a lookup result.
    Some lookups may return a tuple like (None, actual_value)."""
    if isinstance(value, (list, tuple)) and len(value) >= 2:
        return value[1]
    return value

result = {
    "gamma": _extract(vornik.lookup("gamma")),
    "beta":  _extract(vornik.lookup("beta")),
}
